function getAutomaticServiceName(date=new Date()){const value=getServiceBusinessDate(date).toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'long'});return value.charAt(0).toUpperCase()+value.slice(1)}
function getServiceDisplayName(service){if(!service)return'';const base=getAutomaticServiceName(new Date(service.openedAt||service.closedAt));return service.isEvent&&service.eventLabel?`${base} · ${service.eventLabel}`:base}
function localDateKey(date){return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}T${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}:00`}
function aggregateSales(events,keyMaker){const groups=new Map();events.forEach(event=>{const key=keyMaker(event),value=groups.get(key)||{revenue:0,items:0,orders:0};value.revenue+=event.revenue;value.items+=event.items;value.orders+=event.orders;groups.set(key,value)});return groups}
function renderBarChart(selector,entries,emptyText='Aucune vente enregistrée'){const container=document.querySelector(selector);if(!entries.length){container.innerHTML=`<span class="chart-empty">${emptyText}</span>`;return}const max=Math.max(...entries.map(entry=>entry.value),1);container.innerHTML=entries.map(entry=>`<span class="chart-column"${entry.key!==undefined?` data-chart-key="${entry.key}" tabindex="0"`:''} title="${escapeHTML(entry.title||entry.label)}"><b>${entry.value?format(entry.value):'—'}</b><i class="chart-bar" style="height:${Math.max(3,entry.value/max*55)}px"></i><small>${escapeHTML(entry.label)}</small></span>`).join('')}
function renderLineChart(selector,entries){const container=document.querySelector(selector);container.classList.add('service-line-chart');if(!entries.length){container.innerHTML='<span class="chart-empty">Les ventes horaires apparaîtront ici</span>';return}const width=320,height=92,padX=22,padTop=12,padBottom=18,max=Math.max(...entries.map(entry=>entry.value),1),step=entries.length>1?(width-padX*2)/(entries.length-1):0,points=entries.map((entry,index)=>({x:entries.length>1?padX+index*step:width/2,y:padTop+(max-entry.value)/max*(height-padTop-padBottom),...entry})),path=points.map((point,index)=>`${index?'L':'M'}${point.x},${point.y}`).join(' '),area=`${path} L${points.at(-1).x},${height-padBottom} L${points[0].x},${height-padBottom} Z`;container.innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Encaissement heure par heure"><defs><linearGradient id="serviceLineGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ed7a52" stop-opacity=".34"/><stop offset="1" stop-color="#ed7a52" stop-opacity=".03"/></linearGradient></defs><line class="line-grid" x1="${padX}" y1="${height-padBottom}" x2="${width-padX}" y2="${height-padBottom}"/><path class="line-area" d="${area}"/><path class="line-path" d="${path}"/>${points.map(point=>`<circle cx="${point.x}" cy="${point.y}" r="4"><title>${escapeHTML(point.label)} · ${format(point.value)}</title></circle><text x="${point.x}" y="${height-4}" text-anchor="middle">${escapeHTML(point.label)}</text>`).join('')}</svg>`}
