function addToCart(amount,name,logName=name){ if(appMode==='tab'&&!requireName())return; cart.push({amount,name,logName}); renderCart(); toast(`${name} ajouté · total ${format(cart.reduce((s,x)=>s+x.amount,0))}`); }

const NAV_MODE_KEY='mojito-inn-last-screen',NAV_GROUP_KEY='mojito-inn-last-group',navGroupDefaults={sales:{mode:'order'},management:{mode:'expenses'},animation:{mode:'games'},communication:{mode:'misc',target:'cocktails'}};
let activeNavGroup='sales',activeMiscTarget='';
function showNavGroup(group){activeNavGroup=navGroupDefaults[group]?group:'sales';document.querySelectorAll('[data-nav-group]').forEach(button=>button.classList.toggle('active',button.dataset.navGroup===activeNavGroup));document.querySelectorAll('[data-nav-tools]').forEach(row=>row.hidden=row.dataset.navTools!==activeNavGroup);localStorage.setItem(NAV_GROUP_KEY,activeNavGroup)}
function inferNavGroup(mode){if(['order','tab','gifts'].includes(mode))return'sales';if(['expenses','service','control'].includes(mode))return'management';if(mode==='games')return'animation';return['management','animation','communication'].includes(activeNavGroup)?activeNavGroup:'communication'}
function setAppMode(next,group='',silent=false){
  appMode=next; cart=[];
  document.body.classList.toggle('order-mode',appMode==='order');
  document.body.classList.toggle('expenses-mode',appMode==='expenses');
  document.body.classList.toggle('raffle-mode',appMode==='raffle');
  document.body.classList.toggle('gifts-mode',appMode==='gifts');
  document.body.classList.toggle('service-mode',appMode==='service');
  document.body.classList.toggle('games-mode',appMode==='games');
  document.body.classList.toggle('misc-mode',appMode==='misc');
  document.body.classList.toggle('control-mode',appMode==='control');
  showNavGroup(group||inferNavGroup(appMode));
  document.querySelectorAll('[data-app-mode]').forEach(button=>button.classList.toggle('active',button.dataset.appMode===appMode));
  document.querySelectorAll('[data-misc-direct]').forEach(button=>button.classList.toggle('active',appMode==='misc'&&button.dataset.miscDirect===activeMiscTarget));
  localStorage.setItem(NAV_MODE_KEY,appMode);
  document.querySelector('.section-heading small').textContent=appMode==='tab'?'Touchez pour ajouter au panier':'Calcule la commande sans toucher à l’ardoise';
  renderCart();if(!silent){refresh();toast(appMode==='tab'?'Mode ardoise partagé':appMode==='order'?'Mode commande simple':appMode==='expenses'?'Suivi des dépenses':appMode==='gifts'?'Suivi des cadeaux':appMode==='service'?'Gestion du service':appMode==='control'?'Contrôle de l’équipe':appMode==='misc'?'Informations diverses':appMode==='raffle'?'Tombola partagée':'Classement des jeux')}
}
function openMiscSection(target,group='communication'){activeMiscTarget=target;setAppMode('misc',group);setTimeout(()=>{const section=document.querySelector(miscSectionTargets[target]);if(section)section.scrollIntoView({behavior:'smooth',block:'start'})},80)}
document.querySelectorAll('[data-nav-group]').forEach(button=>button.addEventListener('click',()=>{const group=button.dataset.navGroup,destination=navGroupDefaults[group];showNavGroup(group);if(destination.target){activeMiscTarget=destination.target;setAppMode(destination.mode,group)}else setAppMode(destination.mode,group)}));
