let currentOpeningTitle='🌅 LE MOJITO INN EST OUVERT ! 🍹',currentOpeningHook='La journée se termine, venez profiter d’une ambiance chill. On vous attend à Paleto ! 🌅🤙',recentOpeningTitles=[],recentOpeningHooks=[];
function randomOpeningPart(parts){return parts[Math.floor(Math.random()*parts.length)]}
function stripOpeningEmojis(text){return text.replace(/^[^\p{L}\p{N}]+/u,'').replace(/\s+[^\p{L}\p{N}!?]+$/u,'')}
function updateOpeningPhrase(){document.querySelector('#opening-phrase').value=`${currentOpeningTitle}\n${currentOpeningHook}`}
function generateOpeningTitle(){let title,attempts=0;do{const headlines=Math.random()<.85?openingOpenHeadlines:openingHeadlines,[left,right]=randomOpeningPart(openingEmojiPairs);title=`${left} ${stripOpeningEmojis(randomOpeningPart(headlines))} ${right}`;attempts++}while(recentOpeningTitles.includes(title)&&attempts<100);currentOpeningTitle=title;recentOpeningTitles.unshift(title);recentOpeningTitles=recentOpeningTitles.slice(0,60);updateOpeningPhrase()}
function generateOpeningHook(){let hook,attempts=0;do{const[endLeft,endRight]=randomOpeningPart(openingEmojiPairs);hook=`${randomOpeningPart(openingStarts)}, ${randomOpeningPart(openingMiddles)}. ${stripOpeningEmojis(randomOpeningPart(openingEnds))} ${endLeft}${endRight}`;attempts++}while(recentOpeningHooks.includes(hook)&&attempts<100);currentOpeningHook=hook;recentOpeningHooks.unshift(hook);recentOpeningHooks=recentOpeningHooks.slice(0,60);updateOpeningPhrase()}
function changeOpeningEmojis(){const[left,right]=randomOpeningPart(openingEmojiPairs),[endLeft,endRight]=randomOpeningPart(openingEmojiPairs);currentOpeningTitle=`${left} ${stripOpeningEmojis(currentOpeningTitle)} ${right}`;currentOpeningHook=`${stripOpeningEmojis(currentOpeningHook)} ${endLeft}${endRight}`;updateOpeningPhrase()}
updateOpeningPhrase();
