function isYouTubeLink(url){try{return['youtube.com','www.youtube.com','youtu.be','m.youtube.com'].includes(new URL(url).hostname.toLowerCase())}catch{return false}}
function isDirectVideoLink(url){try{return/\.(mp4|webm|m4v|mov|ogv)(?:$|[?#])/i.test(new URL(url).href)}catch{return false}}
function youtubeVideoId(url){try{const parsed=new URL(url);if(parsed.hostname.toLowerCase()==='youtu.be')return parsed.pathname.split('/').filter(Boolean)[0]||'';if(parsed.pathname.startsWith('/shorts/'))return parsed.pathname.split('/')[2]||'';return parsed.searchParams.get('v')||''}catch{return''}}
function renderImportantImages(){const images=importantImages.filter(image=>!isYouTubeLink(image.url)),playlists=importantImages.filter(image=>isYouTubeLink(image.url));document.querySelector('#important-image-list').innerHTML=images.map(image=>{const video=isDirectVideoLink(image.url),media=video?`<video src="${escapeHTML(image.url)}" muted loop playsinline preload="metadata" aria-label="${escapeHTML(image.title)}"></video>`:`<img src="${escapeHTML(image.url)}" alt="${escapeHTML(image.title)}" loading="lazy">`;return`<article class="important-image"><button class="important-image-copy" type="button" data-important-copy="${escapeHTML(image.url)}" data-media-type="${video?'video':'image'}" title="Cliquer pour copier le lien">${media}<b>${escapeHTML(image.title)}</b></button>${image.fixed?'':`<button class="important-image-remove" type="button" data-important-remove="${image.id}" title="Supprimer cet élément">×</button>`}</article>`}).join('');document.querySelector('#playlist-list').innerHTML=playlists.map(image=>{const id=youtubeVideoId(image.url),thumbnail=id?`https://i.ytimg.com/vi/${id}/hqdefault.jpg`:'';return`<article class="important-image playlist-link"><button class="playlist-link-copy" type="button" data-important-copy="${escapeHTML(image.url)}" title="Cliquer pour copier le lien YouTube">${thumbnail?`<img src="${thumbnail}" alt="Miniature ${escapeHTML(image.title)}" loading="lazy">`:'<span class="playlist-play">▶</span>'}<span class="playlist-caption"><b>${escapeHTML(image.title)}</b><small>Cliquer pour copier</small></span></button>${image.fixed?'':`<button class="important-image-remove" type="button" data-important-remove="${image.id}" title="Supprimer cet élément">×</button>`}</article>`}).join('');document.querySelector('#playlist-section').hidden=!playlists.length}
function renderTruckInventory(){let total=0;const totals=new Map();document.querySelector('#truck-inventory-list').innerHTML=truckInventory.sort((a,b)=>a.position-b.position).map(truck=>{const items=parseTruckContents(truck.contents);items.forEach(item=>{total+=item.quantity;const key=item.name.toLocaleLowerCase('fr'),current=totals.get(key)||{name:item.name,quantity:0};current.quantity+=item.quantity;totals.set(key,current)});return `<article class="truck-item"><div class="truck-item-head"><b>🚚 Camion ${truck.position}</b><span>N°${escapeHTML(truck.number)}</span></div>${items.length?`<ul>${items.map(item=>`<li>${item.quantity}× ${escapeHTML(item.name)}</li>`).join('')}</ul>`:'<span class="truck-empty">Camion vide</span>'}<button class="truck-edit" type="button" data-truck-edit="${escapeHTML(truck.number)}">Modifier</button></article>`}).join('');document.querySelector('#truck-total-count').textContent=`${total} unité${total>1?'s':''}`;document.querySelector('#truck-total-detail').innerHTML=totals.size?[...totals.values()].sort((a,b)=>a.name.localeCompare(b.name,'fr')).map(item=>`<span><b>${escapeHTML(item.name)}</b><em>${item.quantity}</em></span>`).join(''):'<span class="truck-draft-empty">Tous les camions sont vides</span>'}
renderImportantImages();
renderTruckInventory();
const importantImagePreview=document.querySelector('#important-image-preview');
function showImportantImagePreview(button){const rect=button.getBoundingClientRect(),previewWidth=Math.min(280,window.innerWidth-28),previewHeight=window.innerWidth<=430?165:210,img=document.querySelector('#important-image-preview-img'),video=document.querySelector('#important-image-preview-video'),isVideo=button.dataset.mediaType==='video';img.hidden=isVideo;video.hidden=!isVideo;if(isVideo){video.src=button.dataset.importantCopy;video.play().catch(()=>{})}else{img.src=button.dataset.importantCopy;img.alt=button.querySelector('b').textContent}document.querySelector('#important-image-preview-title').textContent=`${button.querySelector('b').textContent} · clique pour copier`;importantImagePreview.style.left=`${Math.max(10,Math.min(window.innerWidth-previewWidth-10,rect.left+rect.width/2-previewWidth/2))}px`;importantImagePreview.style.top=`${rect.bottom+previewHeight+10<window.innerHeight?rect.bottom+7:Math.max(10,rect.top-previewHeight-7)}px`;importantImagePreview.classList.add('show');importantImagePreview.setAttribute('aria-hidden','false')}
function hideImportantImagePreview(){importantImagePreview.classList.remove('show');importantImagePreview.setAttribute('aria-hidden','true');const video=document.querySelector('#important-image-preview-video');video.pause();video.removeAttribute('src');video.load();document.querySelector('#important-image-preview-img').removeAttribute('src')}
document.querySelector('#important-image-list').addEventListener('pointerover',event=>{const button=event.target.closest('.important-image-copy');if(button&&!button.contains(event.relatedTarget))showImportantImagePreview(button)});
document.querySelector('#important-image-list').addEventListener('pointerout',event=>{const button=event.target.closest('.important-image-copy');if(button&&!button.contains(event.relatedTarget))hideImportantImagePreview()});
document.querySelector('#important-image-list').addEventListener('focusin',event=>{const button=event.target.closest('.important-image-copy');if(button)showImportantImagePreview(button)});
document.querySelector('#important-image-list').addEventListener('focusout',event=>{if(event.target.closest('.important-image-copy'))hideImportantImagePreview()});
const deleteImageModal=document.querySelector('#delete-image-modal');let pendingDeleteImageId=null;
async function handleImportantMediaClick(event){const copy=event.target.closest('[data-important-copy]'),remove=event.target.closest('[data-important-remove]');if(copy)return copyText(copy.dataset.importantCopy);if(remove){if(!requireName()||!db)return;pendingDeleteImageId=Number(remove.dataset.importantRemove);document.querySelector('#delete-image-error').textContent='';document.querySelector('#delete-image-password').value='';deleteImageModal.showModal();setTimeout(()=>document.querySelector('#delete-image-password').focus(),50)}}
