document.querySelector('#delete-image-form').addEventListener('submit',async event=>{event.preventDefault();if(!db||!pendingDeleteImageId)return;const password=document.querySelector('#delete-image-password').value,errorBox=document.querySelector('#delete-image-error'),button=event.submitter;button.disabled=true;errorBox.textContent='Vérification…';const{data:valid,error:verifyError}=await db.rpc('verifier_acces_application',{p_password:password});if(verifyError||!valid){button.disabled=false;errorBox.textContent=verifyError?verifyError.message:'Mot de passe incorrect';document.querySelector('#delete-image-password').select();return}const{error}=await db.rpc('supprimer_image_importante',{p_id:pendingDeleteImageId,p_operator_name:operatorName});button.disabled=false;if(error){errorBox.textContent=error.message;return}pendingDeleteImageId=null;deleteImageModal.close();await refresh();toast('Image supprimée pour tout le monde ✓')});
document.querySelector('#important-image-form').addEventListener('submit',async event=>{event.preventDefault();if(!requireName()||!db)return toast('Branche d’abord la base Supabase');const title=document.querySelector('#important-image-title').value.trim(),url=document.querySelector('#important-image-url').value.trim();try{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))throw new Error()}catch{return toast('Entre un lien valide')}const{error}=await db.rpc('ajouter_image_importante',{p_title:title,p_url:url,p_operator_name:operatorName});if(error)return toast(error.message.includes('important_images_url_key')?'Ce lien existe déjà : lance le correctif des images dans Supabase':`Élément non ajouté : ${error.message}`);event.target.reset();event.target.closest('details').open=false;await refresh();toast(isYouTubeLink(url)?'Playlist partagée avec tout le monde ✓':'Image partagée avec tout le monde ✓')});
const truckModal=document.querySelector('#truck-modal');
const truckProductSuggestions=['Rhum','Whisky','Vodka','Tequila','Gin','Mojito','Havana Sunset','Blue Crush','Coral Rush','Point Break','Sangria','Cocktail divers','Burger','Hot Dog','Cola','Sprunk','Café','Junk Energy','Eau','Donut','Chips','Alcool de grain','Alcool de pomme de terre','Alcool d’agave','Alcool de canne','Alcool de raisin'];let truckDraftItems=[];
document.querySelector('#truck-item-suggestions').innerHTML=truckProductSuggestions.map(name=>`<option value="${escapeHTML(name)}"></option>`).join('');
function parseTruckContents(contents){return String(contents||'').split('\n').map(line=>line.trim()).filter(Boolean).map(line=>{const match=line.match(/^(\d+)\s*x\s+(.+)$/i);return match?{quantity:Number(match[1]),name:match[2].trim()}:{quantity:1,name:line}})}
function renderTruckDraft(){document.querySelector('#truck-draft-list').innerHTML=truckDraftItems.length?truckDraftItems.map((item,index)=>`<div class="truck-draft-item"><span>${escapeHTML(item.name)}</span><input type="number" min="1" max="9999" value="${item.quantity}" data-truck-draft-quantity="${index}" aria-label="Quantité de ${escapeHTML(item.name)}"><button type="button" data-truck-draft-remove="${index}" title="Retirer">×</button></div>`).join(''):'<div class="truck-draft-empty">Aucun produit dans ce camion</div>'}
document.querySelector('#truck-inventory-list').addEventListener('click',event=>{const button=event.target.closest('[data-truck-edit]');if(!button||!requireName())return;const truck=truckInventory.find(item=>item.number===button.dataset.truckEdit);if(!truck)return;truckDraftItems=parseTruckContents(truck.contents);document.querySelector('#truck-number').value=truck.number;document.querySelector('#truck-modal-title').textContent=`Camion ${truck.position} · N°${truck.number}`;document.querySelector('#truck-item-name').value='';document.querySelector('#truck-item-quantity').value='1';renderTruckDraft();truckModal.showModal();setTimeout(()=>document.querySelector('#truck-item-name').focus(),50)});
document.querySelector('#truck-add-item').addEventListener('click',()=>{const input=document.querySelector('#truck-item-name'),quantityInput=document.querySelector('#truck-item-quantity'),name=input.value.trim(),quantity=Math.max(1,Number(quantityInput.value)||1);if(!name)return toast('Choisis ou écris un produit');const existing=truckDraftItems.find(item=>item.name.localeCompare(name,'fr',{sensitivity:'base'})===0);if(existing)existing.quantity+=quantity;else truckDraftItems.push({name,quantity});input.value='';quantityInput.value='1';renderTruckDraft();input.focus()});
document.querySelector('#truck-item-name').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();document.querySelector('#truck-add-item').click()}});
document.querySelector('#truck-draft-list').addEventListener('click',event=>{const button=event.target.closest('[data-truck-draft-remove]');if(!button)return;truckDraftItems.splice(Number(button.dataset.truckDraftRemove),1);renderTruckDraft()});
document.querySelector('#truck-draft-list').addEventListener('input',event=>{const input=event.target.closest('[data-truck-draft-quantity]');if(!input)return;truckDraftItems[Number(input.dataset.truckDraftQuantity)].quantity=Math.max(1,Math.min(9999,Number(input.value)||1))});
document.querySelector('#close-truck-modal').addEventListener('click',()=>truckModal.close());

function getRoomWeekRange(offset=roomWeekOffset){const now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),now.getDate());start.setDate(start.getDate()-start.getDay());start.setHours(20,0,0,0);if(now<start)start.setDate(start.getDate()-7);start.setDate(start.getDate()+offset*7);const end=new Date(start);end.setDate(end.getDate()+7);return{start,end}}
function roomSlotDate(dayIndex,slotIndex){const{start}=getRoomWeekRange(),date=new Date(start);date.setDate(date.getDate()+dayIndex);date.setHours(21+slotIndex,0,0,0);return date}
function formatRoomTime(date){return date.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}
