function showVoiceDraft(draft){voiceDraft=draft;const total=draft.items.reduce((sum,item)=>sum+item.price*item.quantity,0),itemCount=draft.items.reduce((sum,item)=>sum+item.quantity,0),productOptions=VOICE_PRODUCTS.map(product=>product.name);document.querySelector('#voice-transcript').textContent=`« ${draft.transcript} »`;document.querySelector('#voice-lines').innerHTML=draft.items.map((item,index)=>`<div class="voice-edit-line${item.uncertain?' voice-uncertain':''}"><select data-voice-product="${index}" aria-label="Produit reconnu">${productOptions.map(name=>`<option${name===item.name?' selected':''}>${escapeHTML(name)}</option>`).join('')}</select><input type="number" min="1" max="999" value="${item.quantity}" data-voice-quantity="${index}" aria-label="Quantité de ${escapeHTML(item.name)}"><b>${draft.intent==='truck'?`${item.quantity} unité${item.quantity>1?'s':''}`:format(item.quantity*item.price)}</b><button type="button" data-voice-remove="${index}" title="Retirer">×</button>${item.uncertain?`<small class="voice-warning">Quantité ou prononciation à vérifier</small>`:''}${item.learned?`<small class="voice-learned">Synonyme personnel reconnu : « ${escapeHTML(item.alias)} »</small>`:''}</div>`).join('');document.querySelector('#voice-total').textContent=draft.intent==='truck'?`${itemCount} unité${itemCount>1?'s':''} à ajouter`:`${itemCount} article${itemCount>1?'s':''} · ${format(total)}`;const select=document.querySelector('#voice-truck-select');select.innerHTML=truckInventory.sort((a,b)=>a.position-b.position).map(truck=>`<option value="${escapeHTML(truck.number)}">Camion ${truck.position} · N°${escapeHTML(truck.number)}</option>`).join('');const detected=truckInventory.find(truck=>truck.position===draft.truckPosition);if(detected)select.value=detected.number;const isTruck=draft.intent==='truck';document.querySelector('#voice-truck-choice').hidden=!isTruck;document.querySelector('#voice-to-truck').hidden=!isTruck;document.querySelector('#voice-to-tab').hidden=isTruck;document.querySelector('#voice-to-order').hidden=isTruck;document.querySelector('#voice-to-tab').disabled=!db||total>state.balance||draft.items.some(item=>!item.price);const uncertain=draft.items.filter(item=>item.uncertain).length;document.querySelector('#voice-confirm-note').textContent=!db?'Supabase n’est pas connecté.':total>state.balance&&!isTruck?`Ardoise insuffisante : ${format(state.balance)} restants.`:uncertain?`${uncertain} élément${uncertain>1?'s':''} à vérifier avant validation.`:'Tout semble correctement reconnu. Tu peux encore modifier chaque ligne.';voiceModal.dataset.intent=draft.intent;renderVoiceAliases();if(!voiceModal.open){const settings=voiceModal.querySelector('.voice-alias-settings');if(settings)settings.open=false;voiceModal.showModal()}}
