function applyVoiceContinuation(previous,draft){const text=normalizeVoice(draft.transcript),items=previous.items.map(item=>({...item})),destinationOnly=!draft.items.length&&/(ardoise|commande|encaisse|camion)/.test(text);let intent=/(camion)/.test(text)?'truck':/(commande|encaisse)/.test(text)?'order':/ardoise/.test(text)?'tab':previous.intent,truckPosition=draft.truckPosition||previous.truckPosition;if(/(annule|supprime|enleve|retire)\s+(le\s+)?dernier/.test(text)){items.pop();return{...previous,transcript:`${previous.transcript} + ${draft.transcript}`,items,intent,truckPosition,correction:true}}if(/\b(remplace|change)\b/.test(text)&&/\bpar\b/.test(text)){const [left,right]=draft.transcript.split(/\bpar\b/i),from=parseVoiceCommand(left),to=parseVoiceCommand(right);if(from.items[0]&&to.items[0]){const index=items.findIndex(item=>item.name===from.items[0].name);if(index>=0)items.splice(index,1);const existing=items.find(item=>item.name===to.items[0].name&&item.price===to.items[0].price);if(existing)existing.quantity=to.items[0].quantity;else items.push(to.items[0]);return{...previous,transcript:`${previous.transcript} + ${draft.transcript}`,items,intent,truckPosition,correction:true}}}if(/\b(supprime|enleve|retire)\b/.test(text)&&draft.items.length){draft.items.forEach(removal=>{const index=items.findIndex(item=>item.name===removal.name);if(index<0)return;if(removal.explicitQuantity&&items[index].quantity>removal.quantity)items[index].quantity-=removal.quantity;else items.splice(index,1)});return{...previous,transcript:`${previous.transcript} + ${draft.transcript}`,items,intent,truckPosition,correction:true}}if(destinationOnly)return{...previous,transcript:`${previous.transcript} + ${draft.transcript}`,items,intent,truckPosition,correction:true};draft.items.forEach(item=>{const existing=items.find(saved=>saved.name===item.name&&saved.price===item.price);if(existing)existing.quantity+=item.quantity;else items.push(item)});return{...previous,transcript:`${previous.transcript} + ${draft.transcript}`,items,intent,truckPosition}}
function voiceFailureMessage(transcript){const text=normalizeVoice(transcript);if(!text)return'Je n’ai entendu aucune phrase. Rapproche-toi du micro et réessaie.';if(/\b(ardoise|commande|camion)\b/.test(text))return'La destination est comprise, mais aucun produit ne correspond à la carte.';if(/\d|\b(un|une|deux|trois|quatre|cinq|six|sept|huit|neuf|dix|vingt|trente)\b/.test(text))return'La quantité semble comprise, mais pas le produit. Essaie son nom exact ou ajoute un synonyme.';return'Produit et quantité non reconnus. Essaie par exemple : « 2 mojitos et 1 whisky ».'}
function startVoiceCommand(append=false){if(!SpeechRecognition)return toast('La saisie vocale nécessite Chrome ou Edge');if(!requireName())return;const previousDraft=append&&voiceDraft?{...voiceDraft,items:voiceDraft.items.map(item=>({...item}))}:null;if(append&&voiceModal.open)voiceModal.close();voiceRecognition=new SpeechRecognition();voiceRecognition.lang='fr-FR';voiceRecognition.interimResults=false;voiceRecognition.continuous=false;voiceRecognition.maxAlternatives=10;if(SpeechGrammarList){try{const grammar=new SpeechGrammarList(),words=[...new Set(VOICE_PRODUCTS.flatMap(product=>productVoiceAliases(product)))].join(' | ');grammar.addFromString(`#JSGF V1.0; grammar mojito; public <commande> = (un | deux | trois | quatre | cinq | six | sept | huit | neuf | dix | vingt | trente | quarante | cinquante | cent)+ (${words})+ (ardoise | commande simple | camion | supprime | remplace | retire)?;`,1);voiceRecognition.grammars=grammar}catch(error){console.debug('Grammaire vocale non prise en charge',error)}}voiceRecognition.onstart=()=>{setVoiceListening(true);toast(append?'Continue ou corrige ta commande…':'Écoute en français (France)…')};voiceRecognition.onend=()=>{setVoiceListening(false);if(append&&previousDraft&&!voiceModal.open)showVoiceDraft(voiceDraft||previousDraft)};voiceRecognition.onerror=event=>{setVoiceListening(false);toast(event.error==='not-allowed'?'Autorise le microphone dans le navigateur':event.error==='no-speech'?'Aucune voix détectée. Parle un peu plus près du micro.':'Reconnaissance interrompue, réessaie')};voiceRecognition.onresult=event=>{const result=event.results[event.resultIndex];setVoiceListening(false);const alternatives=[...result].map(item=>({transcript:item.transcript,confidence:Number(item.confidence)||.5})),drafts=alternatives.map(item=>parseVoiceCommand(item.transcript,item.confidence));let draft=drafts.sort((a,b)=>b.recognitionScore-a.recognitionScore)[0];if(append&&previousDraft){draft=applyVoiceContinuation(previousDraft,draft);if(!draft.items.length){voiceDraft=previousDraft;showVoiceDraft(previousDraft);return toast('La correction retirerait toute la commande. Utilise « Tout recommencer » si c’est voulu.')}}else if(!draft.items.length)return toast(voiceFailureMessage(draft.transcript));voiceDraft=draft;showVoiceDraft(draft)};try{voiceRecognition.start()}catch{setVoiceListening(false);if(previousDraft&&!voiceModal.open)showVoiceDraft(previousDraft);toast('Le microphone est déjà en écoute')}}
