function getGlobalSearchEntries(){const rows=[],push=(icon,type,title,details,date,amount='')=>rows.push({icon,type,title:String(title||''),details:String(details||''),date:Number(date)||0,amount:String(amount||'')});state.history.forEach(item=>push('🧾','Ardoise',`${item.quantity>1?item.quantity+' × ':''}${item.name}`,`${item.operator} · ${item.type==='add'?'ajout':'déduction'}`,item.date,item.type==='add'?`+ ${format(item.amount)}`:`− ${format(item.amount)}`));const archived=(services.history||[]).flatMap(service=>Array.isArray(service.snapshot?.expenses)?service.snapshot.expenses.map(item=>({...item,date:new Date(item.date||service.closedAt).getTime(),archived:true})):[]);[...expenses,...archived].forEach(item=>push(item.category==='Réapro'?'📦':'💸',item.category==='Réapro'?'Réapro':'Dépense',item.label,`${item.operator||'Inconnu'}${item.archived?' · archivée':''}`,item.date,`− ${format(item.amount)}`));savedOrders.forEach(order=>push('🧮','Commande',`${order.items.length} article${order.items.length>1?'s':''} · ${order.items.map(item=>item.name).join(', ')}`,order.operator||operatorName,order.date,format(order.total)));game.logs.forEach(item=>push('🏆','Jeux',`${item.player} · ${item.delta>0?'+':''}${item.delta} point${Math.abs(item.delta)>1?'s':''}`,item.operator,item.date));gifts.forEach(item=>push('🎁','Cadeau',item.name,`${item.operator} · ${item.type==='drink'?item.remaining+' conso restante'+(item.remaining>1?'s':''):format(item.amount)+' offert'}`,item.date));(services.history||[]).forEach(service=>push('📊','Service',service.name,`Fermé par ${service.closedBy||'Inconnu'}`,new Date(service.closedAt).getTime(),format(service.snapshot?.revenue||0)));return rows.sort((a,b)=>b.date-a.date)}
