async function loadControlLogs(){if(!db||appMode!=='control'||!isAdminName(operatorName)){controlLogs=[];return}const{data,error}=await db.rpc('lire_controle_equipe',{p_requester_name:operatorName,p_week_start:controlWeekStart().toISOString()});if(error){controlLogs=[];toast(error.message.includes('schema cache')?'Installe « installation-controle-equipe.sql » dans Supabase':error.message);return}controlLogs=(data||[]).map(x=>({id:x.id,saleId:x.sale_id,serviceId:x.service_id,service:x.service_name||'Sans service',operator:x.operator_name,source:x.source,action:x.action,item:x.item_name,quantity:Number(x.quantity),unit:Number(x.unit_amount),total:Number(x.total_amount),date:new Date(x.created_at)}))}
function renderControl(){if(!document.querySelector('#control-people'))return;if(!isAdminName(operatorName)){document.querySelector('#control-log').innerHTML='<div class="team-empty">Accès réservé à Kai et Summer.</div>';return}const people=[...new Set(controlLogs.map(x=>x.operator))].sort((a,b)=>a.localeCompare(b,'fr',{sensitivity:'base'}));if(controlEmployee&&!people.includes(controlEmployee))controlEmployee='';document.querySelector('#control-people').innerHTML=people.length?people.map(name=>{const rows=controlLogs.filter(x=>x.operator===name&&x.action==='sale'),total=rows.reduce((s,x)=>s+x.total,0),items=rows.reduce((s,x)=>s+x.quantity,0);return`<button class="control-person ${name===controlEmployee?'active':''}" type="button" data-control-person="${escapeHTML(name)}"><b>${escapeHTML(name)}${isAdminName(name)?' · ADMIN':''}</b><small>${format(total)} encaissés · ${items} articles</small></button>`}).join(''):'<div class="team-empty">Aucune activité conservée cette semaine.</div>';const employeeRows=controlLogs.filter(x=>x.operator===controlEmployee),days=[...new Set(employeeRows.map(x=>localDateKey(new Date(x.date.getTime()-20*3600000))))].sort().reverse(),servicesList=[...new Map(employeeRows.map(x=>[String(x.serviceId||''),x.service])).entries()];const daySelect=document.querySelector('#control-day'),oldDay=daySelect.value;daySelect.innerHTML='<option value="all">Tous les jours</option>'+days.map(day=>`<option value="${day}">${new Date(`${day}T12:00:00`).toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'long'})}</option>`).join('');daySelect.value=days.includes(oldDay)?oldDay:'all';const serviceSelect=document.querySelector('#control-service'),oldService=serviceSelect.value;serviceSelect.innerHTML='<option value="all">Tous les services</option>'+servicesList.map(([id,name])=>`<option value="${escapeHTML(id)}">${escapeHTML(name)}</option>`).join('');serviceSelect.value=servicesList.some(x=>x[0]===oldService)?oldService:'all';const source=document.querySelector('#control-source').value,day=daySelect.value,service=serviceSelect.value,filtered=employeeRows.filter(x=>(source==='all'||x.source===source)&&(day==='all'||localDateKey(new Date(x.date.getTime()-20*3600000))===day)&&(service==='all'||String(x.serviceId||'')===service)),sales=new Map();filtered.forEach(row=>{const key=row.saleId||`legacy-${row.id}`,sale=sales.get(key)||{date:row.date,source:row.source,service:row.service,items:[],total:0,cancelled:false};sale.items.push(row);sale.total+=row.total;if(row.action==='cancel')sale.cancelled=true;sales.set(key,sale)});const rows=[...sales.values()].sort((a,b)=>b.date-a.date);document.querySelector('#control-summary').textContent=controlEmployee?`${controlEmployee} · ${rows.length} opération${rows.length>1?'s':''}`:'Choisis un employé';document.querySelector('#control-log').innerHTML=!controlEmployee?'<div class="team-empty">Choisis un employé pour afficher son activité.</div>':rows.length?rows.map(sale=>`<article class="control-sale ${sale.cancelled?'cancelled':''}"><div class="control-sale-head"><div><b>${sale.source==='tab'?'🧾 Ardoise':'🧮 Commande simple'}${sale.cancelled?' · annulée':''}</b><small>${escapeHTML(sale.service)} · ${sale.date.toLocaleString('fr-FR',{weekday:'short',day:'2-digit',hour:'2-digit',minute:'2-digit'})}</small></div><strong class="${sale.total<=0?'control-cancelled':''}">${sale.total>=0?'+ ':''}${format(sale.total)}</strong></div><div class="control-sale-items">${sale.items.map(item=>`<span>${Math.abs(item.quantity)} × ${escapeHTML(item.item)} · ${format(Math.abs(item.total))}${item.action==='cancel'?' annulé':''}</span>`).join('')}</div></article>`).join(''):'<div class="team-empty">Aucune opération avec ces filtres.</div>'}
document.querySelector('#control-people').addEventListener('click',event=>{const button=event.target.closest('[data-control-person]');if(!button)return;controlEmployee=button.dataset.controlPerson;renderControl()});['control-day','control-service','control-source'].forEach(id=>document.querySelector(`#${id}`).addEventListener('change',renderControl));document.querySelector('#control-week').addEventListener('change',async event=>{controlWeek=event.target.value;controlEmployee='';await loadControlLogs();renderControl()});

let refreshPromise=null;
async function refresh() {
  if(refreshPromise)return refreshPromise;
  refreshPromise=refreshData().finally(()=>{refreshPromise=null});
  return refreshPromise;
}
async function refreshData() {
  if (!db) { syncStatus('Configuration Supabase requise', 'error'); render(); return; }
  await db.rpc('fermer_service_si_inactif');
  if(appMode==='control'&&!isAdminName(operatorName)){setAppMode('order','sales',true);return}
  const wants=(...modes)=>modes.includes(appMode),skip=()=>Promise.resolve({data:[],error:null,skipped:true});
  const roomRange=getRoomWeekRange();
  const [balanceResult, logsResult, expensesResult,raffleSettingsResult,raffleEntriesResult,teamStatsResult,gameSettingsResult,gameScoresResult,gameLogsResult,gameWinnersResult,giftsResult,servicesResult,salesEventsResult,weeklyStatsResult,eventCocktailsResult,importantImagesResult,truckInventoryResult,podiumResult,podiumVideoResult,roomBookingsResult] = await Promise.all([
    db.from('ardoise_state').select('balance,peak,updated_at').eq('id',1).single(),
    db.from('ardoise_logs').select('id,operation,amount,quantity,item_name,operator_name,created_at').order('created_at',{ascending:false}).limit(50),
    wants('expenses','service')?db.from('depenses').select('id,label,category,amount,operator_name,created_at').order('created_at',{ascending:false}).limit(400):skip(),
    wants('raffle')?db.from('tombola_settings').select('ticket_price,max_tickets,last_winner').eq('id',1).single():skip(),
    wants('raffle')?db.from('tombola_entries').select('name,tickets,operator_name').order('created_at',{ascending:true}):skip(),
    db.from('stats_equipe').select('operator_name,revenue,items,orders').or('revenue.gt.0,items.gt.0,orders.gt.0').order('revenue',{ascending:false}),
    wants('games')?db.from('game_settings').select('title,game_type').eq('id',1).single():skip(),
    wants('games')?db.from('game_scores').select('id,name,points'):skip(),
    wants('games')?db.from('game_point_logs').select('player_name,delta,operator_name,created_at').order('created_at',{ascending:false}).limit(50):skip(),
    wants('games')?db.from('game_winners').select('id,game_title,winner_name,points,second_name,second_points,third_name,third_points,standings,created_at').order('created_at',{ascending:false}).limit(3):skip(),
    wants('gifts')?db.from('gifts').select('id,beneficiary,phone,gift_type,quantity,remaining,amount,note,status,operator_name,created_at,completed_at').order('created_at',{ascending:false}).limit(100):skip(),
    db.from('bar_services').select('id,name,status,is_event,event_label,opened_at,opened_by,closed_at,closed_by,snapshot').order('opened_at',{ascending:false}).limit(50),
    wants('service')?db.from('sales_events').select('id,service_id,operator_name,revenue,items,orders,source,note,created_at').gte('created_at',getServiceWeek().start.toISOString()).order('created_at',{ascending:true}).limit(2500):skip(),
    wants('service')?db.rpc('obtenir_stats_hebdomadaires'):skip(),
    wants('misc')?db.from('event_cocktails').select('id,name,recipe,updated_by,updated_at').order('name',{ascending:true}):skip(),
    wants('misc')?db.from('important_images').select('id,title,url,is_fixed,created_by,created_at').order('created_at',{ascending:true}):skip(),
    wants('misc')?db.from('truck_inventory').select('truck_number,position,contents,updated_by,updated_at').order('position',{ascending:true}):skip(),
    db.rpc('obtenir_podium_ardoises'),
    db.from('podium_videos').select('url,week_start,created_by,created_at').order('created_at',{ascending:false}).limit(1).maybeSingle(),
    wants('misc')?db.from('room_bookings').select('id,start_at,end_at,customer_name,phone,paid,amount,note,operator_name,created_at').gte('start_at',roomRange.start.toISOString()).lt('start_at',roomRange.end.toISOString()).order('start_at',{ascending:true}):skip()
  ]);
  if (balanceResult.error || logsResult.error) { syncStatus('Connexion impossible', 'error'); toast('Vérifie la configuration Supabase'); return; }
  const row=balanceResult.data;
  state={ balance:Number(row.balance), peak:Number(row.peak), updated:new Date(row.updated_at).getTime(), history:logsResult.data.map(x=>({id:x.id,type:x.operation,amount:Number(x.amount),quantity:Number(x.quantity||1),name:x.item_name,operator:x.operator_name,date:new Date(x.created_at).getTime()})) };
  if(!expensesResult.skipped)expenses=expensesResult.error?[]:expensesResult.data.map(x=>({id:x.id,label:x.label,category:x.category,amount:Number(x.amount),operator:x.operator_name,date:new Date(x.created_at).getTime()}));
  if(!giftsResult.skipped)gifts=giftsResult.error?[]:giftsResult.data.map(x=>({id:x.id,name:x.beneficiary,phone:x.phone,type:x.gift_type,quantity:Number(x.quantity),remaining:Number(x.remaining),amount:Number(x.amount),note:x.note,status:x.status||'active',operator:x.operator_name,date:new Date(x.created_at).getTime(),completed:x.completed_at?new Date(x.completed_at).getTime():null}));
  if(!raffleSettingsResult.skipped&&!raffleSettingsResult.error&&!raffleEntriesResult.error){raffle={price:Number(raffleSettingsResult.data.ticket_price),max:Number(raffleSettingsResult.data.max_tickets),winner:raffleSettingsResult.data.last_winner,entries:raffleEntriesResult.data.map(x=>({name:x.name,tickets:Number(x.tickets),operator:x.operator_name}))}}
  teamStats=teamStatsResult.error?[]:teamStatsResult.data.map(x=>({name:x.operator_name,revenue:Number(x.revenue),items:Number(x.items),orders:Number(x.orders)}));
  if(!gameSettingsResult.skipped&&!gameSettingsResult.error&&!gameScoresResult.error&&!gameLogsResult.error){game={title:gameSettingsResult.data.title,type:gameSettingsResult.data.game_type,scores:gameScoresResult.data.map(x=>({id:x.id,name:x.name,points:Number(x.points)})),logs:gameLogsResult.data.map(x=>({player:x.player_name,delta:Number(x.delta),operator:x.operator_name,date:new Date(x.created_at).getTime()})),winners:gameWinnersResult.error?[]:gameWinnersResult.data.map(x=>({id:x.id,title:x.game_title,first:{name:x.winner_name,points:Number(x.points)},second:{name:x.second_name,points:Number(x.second_points||0)},third:{name:x.third_name,points:Number(x.third_points||0)},standings:Array.isArray(x.standings)?x.standings.map(player=>({name:player.name,points:Number(player.points)})):[],date:new Date(x.created_at).getTime()})),winnersError:Boolean(gameWinnersResult.error)}}
  services=servicesResult.error?{current:null,history:[]}:{current:servicesResult.data.filter(x=>x.status==='open').map(x=>({id:x.id,name:x.name,isEvent:x.is_event,eventLabel:x.event_label,openedAt:x.opened_at,openedBy:x.opened_by}))[0]||null,history:servicesResult.data.filter(x=>x.status==='closed').map(x=>({id:x.id,name:x.name,isEvent:x.is_event,eventLabel:x.event_label,openedAt:x.opened_at,closedAt:x.closed_at,closedBy:x.closed_by,snapshot:x.snapshot}))};
  if(!salesEventsResult.skipped)salesEvents=salesEventsResult.error?[]:salesEventsResult.data.map(x=>({id:x.id,serviceId:x.service_id,name:x.operator_name,revenue:Number(x.revenue),items:Number(x.items),orders:Number(x.orders),source:x.source,note:x.note,date:new Date(x.created_at).getTime()}));
  if(!weeklyStatsResult.skipped)weeklyStats=weeklyStatsResult.error?[]:(weeklyStatsResult.data||[]).map(x=>({weekStart:x.week_start,day:Number(x.day),name:x.operator_name,revenue:Number(x.revenue),items:Number(x.items),orders:Number(x.orders)}));
  if(!eventCocktailsResult.skipped)eventCocktails=eventCocktailsResult.error?[]:(eventCocktailsResult.data||[]).map(x=>({id:x.id,name:x.name,recipe:x.recipe,updatedBy:x.updated_by,updatedAt:x.updated_at}));
  if(!importantImagesResult.skipped&&!importantImagesResult.error){const shared=(importantImagesResult.data||[]).map(x=>({id:x.id,title:x.title,url:x.url,fixed:Boolean(x.is_fixed),createdBy:x.created_by}));importantImages=[...fixedImportantMedia.filter(item=>!shared.some(saved=>saved.url===item.url)),...shared]}
  if(!truckInventoryResult.skipped&&!truckInventoryResult.error)truckInventory=(truckInventoryResult.data||[]).map(x=>({number:String(x.truck_number),position:Number(x.position),contents:x.contents||'',updatedBy:x.updated_by||''}));
  if(!podiumResult.skipped&&!podiumResult.error){const value=podiumResult.data||{};ardoisePodium={weekStart:value.week_start,weekEnd:value.week_end,ranking:(value.ranking||[]).map(x=>({name:x.name,total:Number(x.total)})),names:value.names||[]};podiumWeeks=(value.weeks||[]).map(week=>({weekStart:week.week_start,weekEnd:week.week_end,ranking:(week.ranking||[]).map(x=>({name:x.name,total:Number(x.total)}))}))}
  if(!podiumVideoResult.error&&podiumVideoResult.data)latestPodiumVideo={url:podiumVideoResult.data.url,weekStart:podiumVideoResult.data.week_start,createdBy:podiumVideoResult.data.created_by,createdAt:podiumVideoResult.data.created_at};
  if(!roomBookingsResult.skipped){roomBookingsError=Boolean(roomBookingsResult.error);roomBookings=roomBookingsResult.error?[]:(roomBookingsResult.data||[]).map(x=>({id:Number(x.id),start:new Date(x.start_at),end:new Date(x.end_at),name:x.customer_name,phone:x.phone||'',paid:Boolean(x.paid),amount:Number(x.amount)||0,note:x.note||'',operator:x.operator_name}))}
  if(appMode==='control')await loadControlLogs();
  syncStatus('Ardoise partagée · en direct','online'); render();renderExpenses();renderGifts();renderRaffle();renderTeamStats();renderOrderLogs();renderGame();renderPreviousWinners();renderServices();renderDivers();renderImportantImages();renderTruckInventory();renderArdoisePodium();renderLatestPodiumVideo();renderRoomPlanner();renderControl();
}

async function addTransaction(type, amount, name, debtorName='',includeInPodium=true) {
  if (!requireName()) return;
  if (!db) return toast('Branche d’abord la base Supabase');
  if (type==='payment' && amount>state.balance) return toast(`Solde insuffisant : il reste ${format(state.balance)}`);
  const { error }=type==='add'?await db.rpc('ajouter_ardoise_nominative',{p_amount:amount,p_debtor_name:debtorName,p_operator_name:operatorName,p_include_in_podium:includeInPodium}):await db.rpc('appliquer_operation',{p_operation:type,p_amount:amount,p_item_name:name,p_operator_name:operatorName});
  if (error) return toast(error.message.includes('ajouter_ardoise_nominative')||error.message.includes('schema cache')?'Installe le script « podium ardoises » dans Supabase':error.message.includes('Solde insuffisant')?'Le solde vient de changer : montant insuffisant':'Opération non enregistrée');
  if(refreshPromise)await refreshPromise;
  if(type==='add'&&includeInPodium){clearTimeout(podiumSaveTimer);podiumDraftDirty=false;podiumDraftWeek='';podiumOverlayDirty=true}
  await refresh(); toast(type==='add'?`${format(amount)} ajoutés pour ${debtorName} 🌺`:`${name} · − ${format(amount)} ✓`);
}

function updateMenuPrices(){
  document.querySelectorAll('.product[data-normal]').forEach(button=>{const price=happyHour&&button.dataset.happy?button.dataset.happy:button.dataset.normal;button.dataset.price=price;button.querySelector('strong').textContent=price});
  const dynamic=document.querySelectorAll('.dynamic-price');if(dynamic[0])dynamic[0].textContent=happyHour?'350':'450';if(dynamic[1])dynamic[1].textContent=happyHour?'300':'400';
  const toggle=document.querySelector('#happy-toggle');toggle.classList.toggle('active',happyHour);toggle.setAttribute('aria-pressed',happyHour);document.querySelector('#happy-state').textContent=happyHour?'Happy hour · 21h–22h':'Prix classiques';
}
function syncHappyHourAvailability(){const hour=new Date().getHours(),available=hour===21;document.body.classList.toggle('happy-hour-active',available);if(!available&&happyHour){happyHour=false;updateMenuPrices()}return available}
document.querySelector('#happy-toggle').addEventListener('click',()=>{if(!syncHappyHourAvailability())return toast('Happy Hour disponible uniquement entre 21 h et 22 h');happyHour=!happyHour;updateMenuPrices();toast(happyHour?'Happy hour activé 🌅':'Prix classiques activés')});
syncHappyHourAvailability();setInterval(syncHappyHourAvailability,30000);
document.querySelectorAll('[data-menu-view]').forEach(button=>button.addEventListener('click',()=>{const detailed=button.dataset.menuView==='detailed';document.querySelector('#simple-menu').hidden=detailed;document.querySelector('#detailed-menu').hidden=!detailed;document.querySelectorAll('[data-menu-view]').forEach(item=>item.classList.toggle('active',item===button))}));
