function openDayStats(offset){const base=selectedWeek==='current'?getServiceWeek().start:new Date(selectedWeek),date=new Date(base);date.setDate(date.getDate()+offset);date.setHours(21,0,0,0);selectedStatsDay=date;const rows=weeklyStats.filter(row=>row.weekStart===localDateKey(base)&&row.day===date.getDay()),sellers=aggregateSales(rows,row=>row.name||'Inconnu'),knownSellers=[...new Set(['Kai','Summer',...teamStats.map(person=>person.name),...weeklyStats.map(row=>row.name)].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr',{sensitivity:'base'}));document.querySelector('#day-stats-title').textContent=`${date.toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})} · 20 h à 20 h`;document.querySelector('#day-adjust-date').value=date.toISOString();document.querySelector('#day-adjust-person').innerHTML=`<option value="">Choisir un vendeur</option>${knownSellers.map(name=>`<option value="${escapeHTML(name)}">${escapeHTML(name)}${isAdminName(name)?' · ADMIN':''}</option>`).join('')}`;document.querySelector('#day-seller-recap').innerHTML=[...sellers.entries()].sort((a,b)=>b[1].revenue-a[1].revenue).map(([name,value])=>`<div class="week-seller"><b>${escapeHTML(name)}</b><div><span><small>Encaissé</small><strong>${format(value.revenue)}</strong></span><span><small>Articles</small><strong>${value.items}</strong></span><span><small>Commandes</small><strong>${value.orders}</strong></span></div></div>`).join('')||'<div class="team-empty">Aucune vente ce jour-là</div>';document.querySelector('#day-stats-modal').showModal()}
