function updatePWASaverClock(){const now=new Date(),service=document.querySelector('#pwa-saver-service'),wave=document.querySelector('#pwa-saver-wave');document.querySelector('#pwa-saver-time').textContent=now.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});document.querySelector('#pwa-saver-date').textContent=now.toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'long'});service.hidden=!services.current;if(services.current)service.textContent=`Service en cours · ${formatDuration(Math.max(0,now-new Date(services.current.openedAt)))}`;wave.classList.remove('show');requestAnimationFrame(()=>wave.classList.add('show'));clearTimeout(updatePWASaverClock.waveTimer);updatePWASaverClock.waveTimer=setTimeout(()=>wave.classList.remove('show'),1600)}
